------------------
---- MONITORS ----
------------------

-- See https://wiki.hypr.land/Configuring/Basics/Monitors/
-- Fallback for anything not explicitly listed below
hl.monitor({
    output   = "",
    mode     = "preferred",
    position = "auto",
    scale    = "auto",
})

-- Laptop panel (16", 1920x1200 ~141ppi) vs external (27", 1920x1080 ~82ppi):
-- at scale=1 everything renders ~1.7x smaller on the laptop than on the monitor.
-- 1.5 is a common, artifact-free fractional scale that gets it close.
hl.monitor({
    output   = "eDP-1",
    mode     = "preferred",
    position = "1920x0",
    scale    = 1.25,
})

hl.monitor({
    output   = "HDMI-A-1",
    mode     = "preferred",
    position = "0x0",
    scale    = 1,
})


