---------------------
---- KEYBINDINGS ----
---------------------

local mainMod = "SUPER" -- Sets "Windows" key as main modifier

-- Example binds, see https://wiki.hypr.land/Configuring/Basics/Binds/ for more
hl.bind(mainMod .. " + T", hl.dsp.exec_cmd(terminal))
hl.bind(mainMod .. " + SHIFT + T", hl.dsp.exec_cmd(terminal .. " -e env NO_FASTFETCH=1 fish"))  -- terminal without fastfetch banner
local closeWindowBind = hl.bind(mainMod .. " + Q", hl.dsp.window.close())
-- closeWindowBind:set_enabled(false)
hl.bind(mainMod .. " + SHIFT + Q", hl.dsp.window.kill())       -- force-kill an unresponsive window
hl.bind(mainMod .. " + E", hl.dsp.exec_cmd(fileManager))
hl.bind(mainMod .. " + L", hl.dsp.exec_cmd("hyprlock"))  -- lock screen
-- emoji picker (macOS Cmd+Ctrl+Space equivalent). Always copies to clipboard too:
-- wtype's synthetic typing is unreliable in Chromium/Electron apps (e.g. Claude desktop)
hl.bind(mainMod .. " + grave", hl.dsp.exec_cmd("rofimoji --selector wofi --typer wtype --action type clipboard"))
hl.bind(mainMod .. " + V", hl.dsp.window.float({ action = "toggle" }))
hl.bind(mainMod .. " + SHIFT + V", hl.dsp.exec_cmd("copyq toggle"))  -- clipboard history (macOS Cmd+Shift+V equivalent)
hl.bind(mainMod .. " + R", hl.dsp.exec_cmd(menu))
hl.bind(mainMod .. " + N", hl.dsp.window.pseudo())
hl.bind(mainMod .. " + B", hl.dsp.layout("togglesplit"))    -- dwindle only

-- Toggle transparency of the currently focused window: by default all windows
-- are 0.89 opacity (see decoration.*_opacity below); this tags the window
-- "opaque" to override back to fully solid, and untags it to restore 0.89
hl.bind(mainMod .. " + O", hl.dsp.window.tag({ tag = "opaque" }))

-- Fullscreen (mode 2, no gaps/borders) vs Maximize (mode 1, fills screen but keeps gaps)
hl.bind(mainMod .. " + F",         hl.dsp.window.fullscreen({ mode = 1 }))
hl.bind(mainMod .. " + SHIFT + F", hl.dsp.window.fullscreen())

-- Window groups (tabs): put windows in one slot, cycle between them
hl.bind(mainMod .. " + G",     hl.dsp.group.toggle())
hl.bind(mainMod .. " + comma", hl.dsp.group.prev())
hl.bind(mainMod .. " + period",hl.dsp.group.next())

-- Move focus with mainMod + arrow keys
hl.bind(mainMod .. " + left",  hl.dsp.focus({ direction = "left" }))
hl.bind(mainMod .. " + right", hl.dsp.focus({ direction = "right" }))
hl.bind(mainMod .. " + up",    hl.dsp.focus({ direction = "up" }))
hl.bind(mainMod .. " + down",  hl.dsp.focus({ direction = "down" }))

-- Switch focus to the other monitor with mainMod + ALT + left/right
hl.bind(mainMod .. " + ALT + right", hl.dsp.focus({ monitor = "+1" }))
hl.bind(mainMod .. " + ALT + left",  hl.dsp.focus({ monitor = "-1" }))

-- Move the active window to the other monitor with mainMod + ALT + SHIFT + left/right
hl.bind(mainMod .. " + ALT + SHIFT + right", hl.dsp.window.move({ monitor = "+1" }))
hl.bind(mainMod .. " + ALT + SHIFT + left",  hl.dsp.window.move({ monitor = "-1" }))

-- Move the whole current workspace to the other monitor with mainMod + SHIFT + left/right
hl.bind(mainMod .. " + SHIFT + right", hl.dsp.workspace.move({ monitor = "+1" }))
hl.bind(mainMod .. " + SHIFT + left",  hl.dsp.workspace.move({ monitor = "-1" }))

-- Switch workspaces with mainMod + [0-9]
-- Move active window to a workspace with mainMod + SHIFT + [0-9]
for i = 1, 10 do
    local key = i % 10 -- 10 maps to key 0
    hl.bind(mainMod .. " + " .. key,             hl.dsp.focus({ workspace = i}))
    hl.bind(mainMod .. " + SHIFT + " .. key,     hl.dsp.window.move({ workspace = i }))
end

-- Example special workspace (scratchpad)
hl.bind(mainMod .. " + S",         hl.dsp.workspace.toggle_special("magic"))
hl.bind(mainMod .. " + SHIFT + S", hl.dsp.window.move({ workspace = "special:magic" }))

-- Scroll through existing workspaces with mainMod + scroll
hl.bind(mainMod .. " + mouse_down", hl.dsp.focus({ workspace = "e+1" }))
hl.bind(mainMod .. " + mouse_up",   hl.dsp.focus({ workspace = "e-1" }))

-- Move/resize windows with mainMod + LMB/RMB and dragging
hl.bind(mainMod .. " + mouse:272", hl.dsp.window.drag(),   { mouse = true })
hl.bind(mainMod .. " + mouse:273", hl.dsp.window.resize(), { mouse = true })

-- Laptop multimedia keys for volume and LCD brightness
hl.bind("XF86AudioRaiseVolume", hl.dsp.exec_cmd("wpctl set-volume -l 1 @DEFAULT_AUDIO_SINK@ 5%+"), { locked = true, repeating = true })
hl.bind("XF86AudioLowerVolume", hl.dsp.exec_cmd("wpctl set-volume @DEFAULT_AUDIO_SINK@ 5%-"),      { locked = true, repeating = true })
hl.bind("XF86AudioMute",        hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SINK@ toggle"),     { locked = true, repeating = true })
hl.bind("XF86AudioMicMute",     hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SOURCE@ toggle"),   { locked = true, repeating = true })
hl.bind("XF86MonBrightnessUp",  hl.dsp.exec_cmd("brightnessctl -e4 -n2 set 5%+"),                  { locked = true, repeating = true })
hl.bind("XF86MonBrightnessDown",hl.dsp.exec_cmd("brightnessctl -e4 -n2 set 5%-"),                  { locked = true, repeating = true })

-- Requires playerctl
hl.bind("XF86AudioNext",  hl.dsp.exec_cmd("playerctl next"),       { locked = true })
hl.bind("XF86AudioPause", hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })
hl.bind("XF86AudioPlay",  hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })
hl.bind("XF86AudioPrev",  hl.dsp.exec_cmd("playerctl previous"),   { locked = true })

-- Screenshots (hyprshot captures, pipes raw PNG into satty for annotation/save/copy)
-- mirrors macOS Cmd+Shift+3/4/5 muscle memory using Print instead of Super
local screenshotOut = "~/Pictures/Screenshots/screenshot-%Y-%m-%d_%H-%M-%S.png"
local regionShot  = "bash -c 'hyprshot -m region --raw -s | satty -f - -o \"" .. screenshotOut .. "\" --copy-command wl-copy'"
local outputShot  = "bash -c 'hyprshot -m output --raw -s | satty -f - -o \"" .. screenshotOut .. "\" --copy-command wl-copy'"
local windowShot  = "bash -c 'hyprshot -m window --raw -s | satty -f - -o \"" .. screenshotOut .. "\" --copy-command wl-copy'"
local quickCopy   = "hyprshot -m region --clipboard-only"  -- no editor

hl.bind("Print",             hl.dsp.exec_cmd(regionShot))
hl.bind("SHIFT + Print",     hl.dsp.exec_cmd(outputShot))
hl.bind("CTRL + Print",      hl.dsp.exec_cmd(windowShot))
hl.bind("ALT + Print",       hl.dsp.exec_cmd(quickCopy))

-- Fallback bindings: this laptop's built-in keyboard doesn't send a real "Print"
-- keysym on Fn+PrtScn (it sends XF86Calculator instead, quirky firmware) — these
-- work from any keyboard regardless of what the physical Print key does
hl.bind(mainMod .. " + X",              hl.dsp.exec_cmd("hyprshot -m region --clipboard-only"))  -- region -> clipboard
hl.bind(mainMod .. " + SHIFT + X",      hl.dsp.exec_cmd("hyprshot -m output --clipboard-only"))  -- fullscreen -> clipboard
hl.bind(mainMod .. " + ALT + X",        hl.dsp.exec_cmd(regionShot))                             -- region -> satty
hl.bind(mainMod .. " + ALT + SHIFT + X", hl.dsp.exec_cmd(outputShot))                            -- fullscreen -> satty

-- Screen recording: just launches Kooha's own GUI to pick area/mic and start recording
hl.bind(mainMod .. " + SHIFT + R", hl.dsp.exec_cmd("kooha"))


