-- See https://wiki.hypr.land/Configuring/Basics/Window-Rules/
-- and https://wiki.hypr.land/Configuring/Basics/Workspace-Rules/

-- Example window rules that are useful

local suppressMaximizeRule = hl.window_rule({
    -- Ignore maximize requests from all apps. You'll probably like this.
    name  = "suppress-maximize-events",
    match = { class = ".*" },

    suppress_event = "maximize",
})
-- suppressMaximizeRule:set_enabled(false)

hl.window_rule({
    -- Windows tagged "opaque" (via Super+O) override the global 0.89 opacity back to solid.
    -- NOTE: window_rule opacity is a MULTIPLIER on top of decoration.active_opacity (0.89),
    -- so to land on 1.0 we need 1/0.89 here, not 1.0 itself.
    name    = "toggle-transparency",
    match   = { tag = "opaque" },
    opacity = "1.1236 1.1236 1.1236",
})

hl.window_rule({
    -- CopyQ (clipboard history): floating, not tiled into the layout
    name  = "copyq-floating",
    match = { class = "^com.github.hluk.copyq$" },
    float = true,
    size  = "600 700",
})

hl.window_rule({
    -- satty (screenshot annotation): fixed-size floating window, not tiled into the layout
    -- (90% was too big for full-screen shots, overlapped the top bar)
    name  = "satty-floating",
    match = { class = "^com.gabm.satty$" },
    float = true,
    size  = "1400 900",
})

hl.window_rule({
    -- AyuGram: open floating and narrow instead of tiled
    -- (size matches the current on-screen size at eDP-1 scale 1.25)
    name  = "ayugram-floating",
    match = { class = "^com.ayugram.desktop$" },
    float = true,
    size  = "709 892",
})

hl.window_rule({
    -- GNOME Calculator: open floating and small
    name  = "calculator-floating",
    match = { class = "^org.gnome.Calculator$" },
    float = true,
    size  = "400 300",
})

hl.window_rule({
    -- Google Chrome: stays fully opaque, unlike everything else (which defaults to 0.89).
    -- Same compensating multiplier trick as the Super+O "opaque" tag rule above.
    name    = "chrome-opaque",
    match   = { class = "^[Gg]oogle-chrome$" },
    opacity = "1.1236 1.1236 1.1236",
})

hl.window_rule({
    -- gThumb: stays fully opaque too, like Chrome
    name    = "gthumb-opaque",
    match   = { class = "^org.gnome.gThumb$" },
    opacity = "1.1236 1.1236 1.1236",
})

hl.window_rule({
    -- Fix some dragging issues with XWayland
    name  = "fix-xwayland-drags",
    match = {
        class      = "^$",
        title      = "^$",
        xwayland   = true,
        float      = true,
        fullscreen = false,
        pin        = false,
    },

    no_focus = true,
})

